@tool
class_name StoryValidator
extends EditorScript


func _run() -> void:
	print("--- Inizio controllo storia ---")
	validate_chapter("res://story/intro.json")
	print("--- Controllo terminato ---")


func validate_chapter(file_path: String) -> void:
	if not FileAccess.file_exists(file_path):
		printerr("File non trovato: %s" % file_path)
		return

	var file := FileAccess.open(file_path, FileAccess.READ)
	var content: String = file.get_as_text()
	var json_data: Variant = JSON.parse_string(content)

	if not json_data is Dictionary:
		printerr("%s: Il file non contiene un oggetto JSON valido." % file_path)
		return

	var chapter: Dictionary = json_data
	var lines: Array = chapter.get("lines", [])
	var known_speakers: Array[String] = ["Elena", "Marco", "???", ""]
	var declared_labels: Dictionary = {}
	var assigned_variables: Array[String] = []

	# 1. Raccoglie etichette e variabili definite
	for i in range(lines.size()):
		var entry: Variant = lines[i]
		if not entry is Dictionary:
			continue
		var cmd: Dictionary = entry
		var cmd_type: String = String(cmd.get("type", ""))

		if cmd_type == "label":
			var label_name: String = String(cmd.get("name", ""))
			if label_name.is_empty():
				_report_error(file_path, i, "Etichetta senza nome specificato.")
			elif declared_labels.has(label_name):
				_report_error(file_path, i, "Etichetta duplicata: '%s'." % label_name)
			else:
				declared_labels[label_name] = i

		if cmd_type == "set":
			var var_name: String = String(cmd.get("variable", ""))
			if not var_name.is_empty() and not assigned_variables.has(var_name):
				assigned_variables.append(var_name)

	# 2. Controlla personaggi, salti, scelte e condizioni
	for i in range(lines.size()):
		var entry: Variant = lines[i]
		if not entry is Dictionary:
			_report_error(file_path, i, "Elemento non valido nella lista comandi.")
			continue

		var cmd: Dictionary = entry
		var speaker: String = String(cmd.get("speaker", ""))
		if not speaker.is_empty() and not known_speakers.has(speaker):
			_report_error(file_path, i, "Personaggio sconosciuto '%s'." % speaker)

		var cmd_type: String = String(cmd.get("type", ""))
		if cmd_type == "jump":
			var target: String = String(cmd.get("target", ""))
			if not declared_labels.has(target):
				_report_error(file_path, i, "Salto verso etichetta inesistente '%s'." % target)

		if cmd_type == "choice":
			var options: Array = cmd.get("options", [])
			for opt in options:
				if opt is Dictionary:
					var target: String = String(opt.get("target", ""))
					if not declared_labels.has(target):
						_report_error(file_path, i, "Scelta rimanda a etichetta inesistente '%s'." % target)

		if cmd.has("condition") and cmd["condition"] is Dictionary:
			var cond: Dictionary = cmd["condition"]
			var cond_var: String = String(cond.get("variable", ""))
			if not cond_var.is_empty() and not assigned_variables.has(cond_var):
				_report_error(file_path, i, "Condizione usa variabile mai impostata '%s'." % cond_var)

	# 3. Controlla punti mai raggiungibili
	_check_reachability(file_path, lines, declared_labels)


func _check_reachability(file_path: String, lines: Array, labels: Dictionary) -> void:
	var visited_indices: Array[int] = []
	var visited_labels: Array[String] = []

	_traverse_flow(0, lines, labels, visited_indices, visited_labels)

	for i in range(lines.size()):
		if not lines[i] is Dictionary:
			continue
		var cmd: Dictionary = lines[i]
		var cmd_type: String = String(cmd.get("type", ""))
		if not visited_indices.has(i) and cmd_type != "label":
			_report_error(file_path, i, "Comando mai raggiungibile dal flusso della storia.")


func _traverse_flow(current_index: int, lines: Array, labels: Dictionary, visited_indices: Array[int], visited_labels: Array[String]) -> void:
	while current_index < lines.size():
		if visited_indices.has(current_index):
			break
		visited_indices.append(current_index)

		if not lines[current_index] is Dictionary:
			break
		var cmd: Dictionary = lines[current_index]
		var cmd_type: String = String(cmd.get("type", ""))

		if cmd_type == "jump":
			var target: String = String(cmd.get("target", ""))
			if labels.has(target) and not visited_labels.has(target):
				visited_labels.append(target)
				_traverse_flow(labels[target], lines, labels, visited_indices, visited_labels)
			break

		if cmd_type == "choice":
			var options: Array = cmd.get("options", [])
			for opt in options:
				if opt is Dictionary:
					var target: String = String(opt.get("target", ""))
					if labels.has(target) and not visited_labels.has(target):
						visited_labels.append(target)
						_traverse_flow(labels[target], lines, labels, visited_indices, visited_labels)
			break

		current_index += 1


func _report_error(file_path: String, index: int, message: String) -> void:
	print("%s [riga %d]: ERRORE - %s" % [file_path, index, message])
